    // Otherwise, newest timestamp wins, with ties going to the earlier row.
    const hasMissingTimestamp = group.some(r => r.ms === null);
    group.sort((a, b) => hasMissingTimestamp
      ? a.index - b.index
      : b.ms - a.ms || a.index - b.index);

    group.forEach((r, i) => {
      r.dupEmail = 'DUP-email';
      if (i > 0) r.superseded = 'SUPERSEDED';
    });
  }

