  }

  const output = rows.map(r => {
    if (!r) return helperHeaders.map(() => '');
    const needsReview =
      r.joined === 'REVIEW' || r.phone === 'REVIEW' || !r.date ||
      r.park === 'REVIEW' || r.dupEmail || r.dupName;
    return [
      r.joined, r.phone, r.date || 'REVIEW', r.park, r.emailKey, r.nameKey,
      r.dupEmail, r.dupName, r.superseded, needsReview ? 'REVIEW' : 'OK'
    ];
  });

  const missing = helperHeaders.filter(header => !columns.has(header));
  if (missing.length) {
    const start = raw.getLastColumn() + 1;
    const end = start + missing.length - 1;
    if (end > raw.getMaxColumns()) {
      raw.insertColumnsAfter(raw.getMaxColumns(), end - raw.getMaxColumns());
    }
    raw.getRange(1, start, 1, missing.length).setValues([missing]);
    missing.forEach((header, i) => columns.set(header, start + i - 1));
  }

  if (!output.length) return;
  helperHeaders.forEach((header, i) => {
    const range = raw.getRange(2, columns.get(header) + 1, output.length, 1);
    if (header === 'CleanPhone') range.setNumberFormat('@');
    if (header === 'ParsedTimestamp') {
      range.setNumberFormat('yyyy-mm-dd hh:mm:ss');
    }
    // Write literal text even if a source-derived value starts with "=".
    range.setValues(output.map(row => {
      const value = row[i];
      return [typeof value === 'string' && value.startsWith('=')
        ? "'" + value : value];
    }));
  });
}
