```javascript
function cleanVolunteerSurvey() {
  const DATE_ORDER = 'MDY'; // Change to 'DMY' for day/month/year text dates.
  const DEFAULT_AREA_CODE = '415';
  const WINDOW_MS = 10 * 60 * 1000;

  const sourceHeaders = [
    'Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark'
  ];
  const helperHeaders = [
    'NormalizedJoined', 'CleanPhone', 'ParsedTimestamp', 'CleanPark',
    'EmailKey', 'NameKey', 'DupEmailFlag', 'DupNameTimeFlag',
    'Superseded', 'ReviewFlag'
  ];

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getActiveSheet();
  if (raw.getName() !== 'Raw') {
    throw new Error('Select the Raw tab before running this script.');
  }
  if (!['MDY', 'DMY'].includes(DATE_ORDER)) {
    throw new Error('DATE_ORDER must be MDY or DMY.');
  }
  if (!/^\d{3}$/.test(DEFAULT_AREA_CODE)) {
    throw new Error('DEFAULT_AREA_CODE must be exactly three digits.');
  }

  const parkSheet = ss.getSheetByName('ParkMap');
  if (!parkSheet) throw new Error('Missing sheet: ParkMap.');

  const tz = ss.getSpreadsheetTimeZone();
  const text = value => String(value ?? '').trim();
  const parkKey = value => text(value).toLowerCase().replace(/[^a-z]/g, '');
  // Prevent source-derived text from being interpreted as a formula.
  const literal = value =>
    typeof value === 'string' && value.startsWith('=') ? "'" + value : value;

  const parkMap = new Map();
  const mapRowCount = parkSheet.getLastRow() - 1;
  if (mapRowCount > 0) {
    parkSheet.getRange(2, 1, mapRowCount, 2).getDisplayValues()
      .forEach(([alias, canonical], i) => {
        const key = parkKey(alias);
        const name = text(canonical);
        if (!text(alias) && !name) return;
        if (!key || !name) {
          throw new Error(`ParkMap row ${i + 2} needs a valid key and canonical name.`);
        }
        if (parkMap.has(key) && parkMap.get(key) !== name) {
          throw new Error(`Conflicting ParkMap entries for "${key}".`);
        }
        parkMap.set(key, name);
      });
  }

  const values = raw.getDataRange().getValues();
  const headers = values[0].map(text);
  const columns = new Map();

  for (const header of [...sourceHeaders, ...helperHeaders]) {
    const index = headers.indexOf(header);
    if (index !== -1 && index !== headers.lastIndexOf(header)) {
      throw new Error(`Duplicate header in Raw: ${header}`);
    }
    if (index !== -1) columns.set(header, index);
  }
  for (const header of sourceHeaders) {
    if (!columns.has(header)) throw new Error(`Missing Raw header: ${header}`);
  }

  function normalizeJoined(value) {
    const s = text(value).toLowerCase();
    if (/^y(es)?$/.test(s)) return 'Yes';
    if (/^no?$/.test(s)) return 'No';
    return 'REVIEW';
  }

  function cleanPhone(value) {
    let digits = text(value).replace(/\D/g, '');
    if (digits.length === 11 && digits.startsWith('1')) {
      digits = digits.slice(1);
    }
    if (digits.length === 7) {
      digits = DEFAULT_AREA_CODE + digits;
    }
    return digits.length === 10 ? digits : 'REVIEW';
  }

  function parseTimestamp(value) {
    if (value instanceof Date) {
      return Number.isFinite(value.getTime()) ? value : null;
    }

    const s = text(value);
    let year, month, day, hour, minute, second, meridiem;

    // Examples: 4/3/2021 09:12, 3/4/21, 4/3/2021 9:12 AM.
    const numeric = s.match(
      /^(\d{1,2})\/(\d{1,2})\/(\d{4}|\d{2})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\s*(AM|PM))?)?$/i
    );

    if (numeric) {
      const [, first, secondPart, y, h, m, sec, ampm] = numeric;
      [month, day] = DATE_ORDER === 'MDY'
        ? [first, secondPart] : [secondPart, first];
      year = y.length === 2 ? 2000 + Number(y) : Number(y);
      [hour, minute, second, meridiem] = [h, m, sec, ampm];
    } else {
      // Example: 03-Mar-2021, optionally followed by a time.
      const named = s.match(
        /^(\d{1,2})-([a-z]{3})-(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\s*(AM|PM))?)?$/i
      );
      if (!named) return null;

      const [, d, mon, y, h, m, sec, ampm] = named;
      month = ('jan feb mar apr may jun jul aug sep oct nov dec')
        .split(' ').indexOf(mon.toLowerCase()) + 1;
      if (!month) return null;
      [day, year, hour, minute, second, meridiem] = [d, y, h, m, sec, ampm];
    }

    hour = Number(hour || 0);
    if (meridiem) {
      if (hour < 1 || hour > 12) return null;
      hour = hour % 12 + (meridiem.toUpperCase() === 'PM' ? 12 : 0);
    }

    const pad = n => String(Number(n)).padStart(2, '0');
    const stamp = `${year}-${pad(month)}-${pad(day)} ` +
                  `${pad(hour)}:${pad(minute || 0)}:${pad(second || 0)}`;
    const format = 'yyyy-MM-dd HH:mm:ss';

    try {
      const date = Utilities.parseDate(stamp, tz, format);
      // Reject invalid dates/times that the parser silently rolls forward.
      return Utilities.formatDate(date, tz, format) === stamp ? date : null;
    } catch (e) {
      return null;
    }
  }

  const byEmail = new Map();
  const byName = new Map();

  function addToGroup(groups, key, row) {
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(row);
  }

  const rows = values.slice(1).map((row, i) => {
    const fields = sourceHeaders.map(header => row[columns.get(header)]);
    if (fields.every(value => text(value) === '')) return null;

    const [timestamp, name, email, joined, phone, park] = fields;
    const date = parseTimestamp(timestamp);
    const r = {
      index: i,
      joined: normalizeJoined(joined),
      phone: cleanPhone(phone),
      date,
      ms: date ? date.getTime() : null,
      park: text(park) === '' ? 'Unknown' : (parkMap.get(parkKey(park)) || 'REVIEW'),
      emailKey: text(email).toLowerCase(),
      nameKey: text(name).toLowerCase().replace(/\s+/g, ' '),
      dupEmail: '',
      dupName: '',
      superseded: ''
    };
    if (r.emailKey) addToGroup(byEmail, r.emailKey, r);
    if (r.nameKey && r.date) addToGroup(byName, r.nameKey, r);
