  }

  const counts = {
    total: 0, ok: 0, review: 0,
    badJoined: 0, badPhone: 0, badTimestamp: 0, badPark: 0,
    dupEmail: 0, dupName: 0, superseded: 0
  };

  // Include every canonical park, even if no submissions mapped to it.
  const canonicalParks = [...new Set(parkMap.values())]
    .filter(name => name !== 'Unknown' && name !== 'REVIEW')
    .sort((a, b) => a.localeCompare(b));
  const parkCounts = new Map(
    [...canonicalParks, 'Unknown', 'REVIEW'].map(name => [name, 0])
