    if (badPhone) counts.badPhone++;
    if (badTimestamp) counts.badTimestamp++;
    if (badPark) counts.badPark++;
    if (r.dupEmail) counts.dupEmail++;
    if (r.dupName) counts.dupName++;
    if (r.superseded) counts.superseded++;
